$roots = @("C:\Users\eric_rash\Desktop\DEV","C:\Users\eric_rash\Desktop\DEV\Football","C:\Users\eric_rash\Desktop\DEV\SpecialRequests")
$skip = @('.claude','_tools','_DRIVE','token-dashboard','Football','SpecialRequests','.git')
$dirs = foreach ($r in $roots) { if (Test-Path $r) { Get-ChildItem -Path $r -Directory -Force -ErrorAction SilentlyContinue } }
$dirs = $dirs | Where-Object { $skip -notcontains $_.Name -and $_.Name -notmatch '_OLD_merged' -and $_.Name -notmatch '^\.' }
$res = foreach ($d in $dirs) {
  $p = $d.FullName
  if (-not (Test-Path (Join-Path $p '.git'))) { [pscustomobject]@{N=$d.Name;S='NOT-A-REPO';U=0;A=0;B=0} ; continue }
  $rem = (& git -C $p remote get-url origin 2>$null)
  $unc = @(& git -C $p status --porcelain 2>$null).Count
  if (-not $rem) { [pscustomobject]@{N=$d.Name;S='NO-REMOTE';U=$unc;A=0;B=0} ; continue }
  $br = (& git -C $p rev-parse --abbrev-ref HEAD 2>$null)
  $ab = (& git -C $p rev-list --left-right --count "origin/$br...$br" 2>$null)
  $beh=0;$ah=0
  if ($ab) { $parts = $ab -split "\s+"; $beh=[int]$parts[0]; $ah=[int]$parts[1] }
  $tag = if ($rem -notmatch 'erash11') { 'OTHER-REMOTE' } else { 'OK' }
  [pscustomobject]@{N=$d.Name;S=$tag;U=$unc;A=$ah;B=$beh}
}
"TOTAL SCANNED: $($res.Count)"
"--- NEEDS ACTION ---"
$res | Where-Object { $_.S -ne 'OK' -or $_.U -gt 0 -or $_.A -gt 0 -or $_.B -gt 0 } | Sort-Object N | Format-Table -AutoSize | Out-String -Width 120
"--- CLEAN+SYNCED: $(($res | Where-Object { $_.S -eq 'OK' -and $_.U -eq 0 -and $_.A -eq 0 -and $_.B -eq 0 }).Count) ---"

